"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["79130"],{4915(e){e.exports=JSON.parse('{"id":"V4-161","slug":"physical-risk","term":"Physical Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Physical risk is the risk of financial loss from the physical effects of climate change, including extreme weather events and long-term changes in climate patterns.","explanation":["Physical risks are usually divided into two types. Acute risks come from specific events, such as hurricanes, floods, wildfires and heatwaves. Chronic risks come from gradual changes, such as rising temperatures, rising sea levels, changing rainfall and water shortages.","These risks can damage property and infrastructure, disrupt supply chains, reduce agricultural output, increase operating costs and reduce the value of assets. They also affect insurers, which pay claims, and banks, whose borrowers may struggle to repay loans.","For example, a manufacturer with factories in a region prone to flooding may face damage, production stoppages and higher insurance costs. Homeowners in areas facing rising wildfire or flood risk may find insurance becoming more expensive or unavailable, reducing property values.","Companies and investors assess physical risk by analysing the locations of assets and suppliers and modelling how climate change may affect them under different scenarios. Managing physical risk can involve adaptation measures, such as flood defences and more resilient buildings, insurance and avoiding high-risk locations."],"note":"","total":1725,"prev":{"slug":"phishing","term":"Phishing"},"next":{"slug":"pik-interest","term":"PIK Interest"}}')}}]);